class Solution {
public:
    vector<vector<int>> specialGrid(int n) {
        int sz = 1 << n;
        vector<vector<int>> g(sz, vector<int>(sz));
        function<void(int,int,int,int)> fill = [&](int r, int c, int s, int off) {
            if (s == 1) { g[r][c] = off; return; }
            int h = s / 2, q = h * h;
            fill(r, c + h, h, off);
            fill(r + h, c + h, h, off + q);
            fill(r + h, c, h, off + 2 * q);
            fill(r, c, h, off + 3 * q);
        };
        fill(0, 0, sz, 0);
        return g;
    }
};

