var specialGrid = function(n) {
    const sz = 1 << n;
    const g = Array.from({length: sz}, () => new Array(sz).fill(0));
    const fill = (r, c, s, off) => {
        if (s === 1) { g[r][c] = off; return; }
        const h = s >> 1, q = h * h;
        fill(r, c + h, h, off);
        fill(r + h, c + h, h, off + q);
        fill(r + h, c, h, off + 2 * q);
        fill(r, c, h, off + 3 * q);
    };
    fill(0, 0, sz, 0);
    return g;
};
